// Register chunk loading callback
MinecraftForge.EVENT_BUS.addListener(this::onChunkLoad);

private void onChunkLoad(ChunkEvent.Load event) {
    Level world = event.getLevel();
    ChunkPos pos = event.getChunk().getPos();

    // Check if chunk should be forced loaded
    if (shouldForceLoad(pos)) {
        ForgeChunkManager.forceChunk(event.getWorld().getServer(), 
            new ResourceLocation(MODID, "my_forced_chunk"), pos);
    }
}

// Unforce chunk when needed
public void releaseChunk(ChunkPos pos) {
    ForgeChunkManager.unforceChunk(server, 
        new ResourceLocation(MODID, "my_forced_chunk"), pos);
}

// Request chunk ticket for persistent loading
public void requestPersistentLoading(Level world) {
    ForgeChunkManager.getRegistration(world).ifPresent(registration -> {
        registration.getOwner().ifPresent(owner -> {
            ForgeChunkManager.ticketTypeCalled(MODID, owner, () -> 10);
        });
    });
}
